BEGIN TRANSACTION;
LET $__existing = (SELECT VALUE id FROM user WHERE id = $p0 LIMIT 1);
IF array::len($__existing) = 0 THEN CREATE user:aeon CONTENT $p1 RETURN VALUE { before: $before, after: $after } ELSE UPDATE $__existing[0] MERGE $p2 RETURN VALUE { before: $before, after: $after } END;
COMMIT TRANSACTION;

